-- Subscription incarnation registry and observed-state tracking.
-- The identity UUID is generated by PostgreSQL and shared by every projected
-- copy of one MaaS subscription incarnation. Kubernetes UIDs remain local
-- observation fingerprints rather than the shared identity.
CREATE TABLE IF NOT EXISTS subscription_identities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant TEXT NOT NULL,
    namespace TEXT NOT NULL,
    name TEXT NOT NULL,
    rotation_pending_at TIMESTAMPTZ,
    deleted_at TIMESTAMPTZ
);

CREATE UNIQUE INDEX IF NOT EXISTS subscription_identities_active_uq
    ON subscription_identities(tenant, namespace, name)
    WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS subscription_observers (
    observer_id UUID PRIMARY KEY,
    tenant TEXT NOT NULL,
    observed_at TIMESTAMPTZ NOT NULL,
    retired_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS subscription_observations (
    subscription_id UUID NOT NULL REFERENCES subscription_identities(id),
    observer_id UUID NOT NULL REFERENCES subscription_observers(observer_id),
    object_uid TEXT NOT NULL,
    absent_at TIMESTAMPTZ,
    observed_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (subscription_id, observer_id)
);

CREATE INDEX IF NOT EXISTS subscription_observations_observer_object
    ON subscription_observations(observer_id, object_uid);

ALTER TABLE api_keys
    ADD COLUMN IF NOT EXISTS subscription_id UUID
        REFERENCES subscription_identities(id)
        ON DELETE RESTRICT,
    ADD COLUMN IF NOT EXISTS subscription_namespace TEXT;

